-- Creates the payment_authorization_actions table: each capture or void of
-- the authorized hold of a MANUAL payment intent, made through the processor
-- account of its authorized attempt (P-08). It belongs to the payments module.
--
-- An action is inserted as EXECUTING, with its operation_id, before the
-- provider is called (Reserve), and its result is applied afterwards by a
-- conditional update that requires the expected status (Apply). Timestamps
-- have no database default: the application supplies them from its injected
-- clock. Identifiers are UUIDs generated by the application.

CREATE TABLE payment_authorization_actions (
  id uuid NOT NULL,
  merchant_id uuid NOT NULL,
  payment_intent_id uuid NOT NULL,
  -- The authorized attempt whose hold is captured or voided.
  payment_attempt_id uuid NOT NULL,
  -- The account of that attempt, the only one that can act on the hold.
  processor_account_id uuid NOT NULL,
  action varchar(16) NOT NULL,
  -- Stable identity of the provider operation, created before the call: it is
  -- sent as the provider's idempotency key.
  operation_id uuid NOT NULL,
  -- The idempotency record that the request claimed. It stays in progress
  -- while the action is EXECUTING or UNKNOWN. No foreign key: the idempotency
  -- module owns its records.
  idempotency_record_id uuid NOT NULL,
  -- The amount captured or released: always the intent's whole amount.
  amount_minor bigint NOT NULL,
  currency varchar(3) NOT NULL,
  status varchar(20) NOT NULL,
  failure_code varchar(64),
  error_category varchar(20),
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  CONSTRAINT payment_authorization_actions_pkey PRIMARY KEY (id),
  CONSTRAINT payment_authorization_actions_merchant_id_id_key UNIQUE (merchant_id, id),
  CONSTRAINT payment_authorization_actions_operation_id_key UNIQUE (operation_id),
  -- The intent, its attempt, and the account of an action always belong to
  -- its merchant; the attempt belongs to the intent, and the currency is the
  -- intent's.
  CONSTRAINT payment_authorization_actions_payment_intent_fkey FOREIGN KEY (merchant_id, payment_intent_id, currency)
    REFERENCES payment_intents (merchant_id, id, currency),
  CONSTRAINT payment_authorization_actions_payment_attempt_fkey FOREIGN KEY (merchant_id, payment_intent_id, payment_attempt_id)
    REFERENCES payment_attempts (merchant_id, payment_intent_id, id),
  CONSTRAINT payment_authorization_actions_processor_account_fkey FOREIGN KEY (merchant_id, processor_account_id)
    REFERENCES processor_accounts (merchant_id, id),
  CONSTRAINT payment_authorization_actions_action_check CHECK (action IN ('CAPTURE', 'VOID')),
  CONSTRAINT payment_authorization_actions_amount_minor_check CHECK (amount_minor > 0),
  CONSTRAINT payment_authorization_actions_currency_check CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT payment_authorization_actions_status_check CHECK (
    status IN ('EXECUTING', 'SUCCEEDED', 'FAILED', 'UNKNOWN')
  ),
  CONSTRAINT payment_authorization_actions_failure_code_check CHECK (failure_code ~ '^[a-z0-9_]{1,64}$'),
  -- The values mirror PROCESSOR_ERROR_CATEGORIES in packages/processor-contracts.
  CONSTRAINT payment_authorization_actions_error_category_check CHECK (
    error_category IN ('CONFIGURATION', 'NETWORK', 'GATEWAY', 'ISSUER_DECLINE', 'INVALID_REQUEST', 'UNKNOWN')
  ),
  CONSTRAINT payment_authorization_actions_failure_code_status_check CHECK (
    failure_code IS NULL OR status = 'FAILED'
  ),
  -- A failed or uncertain action says why; the others carry no category.
  CONSTRAINT payment_authorization_actions_error_category_status_check CHECK (
    (status IN ('FAILED', 'UNKNOWN')) = (error_category IS NOT NULL)
  )
);

-- Capture and void of one intent exclude each other: at most one action per
-- intent that may have changed its hold (executing, unknown, or succeeded).
-- Only an action the provider proved it did not execute (FAILED) frees the
-- intent for another one.
CREATE UNIQUE INDEX payment_authorization_actions_one_per_intent_idx
  ON payment_authorization_actions (payment_intent_id)
  WHERE status <> 'FAILED';

-- The actions of one intent, oldest first.
CREATE INDEX payment_authorization_actions_merchant_intent_created_at_id_idx
  ON payment_authorization_actions (merchant_id, payment_intent_id, created_at, id);

COMMENT ON TABLE payment_authorization_actions IS 'Captures and voids of the authorized holds of MANUAL payment intents. Rows are never deleted, and a finished action never changes.';
COMMENT ON COLUMN payment_authorization_actions.action IS 'CAPTURE takes the held funds; VOID releases the hold.';
COMMENT ON COLUMN payment_authorization_actions.amount_minor IS 'The amount captured or released, the intent''s whole amount, in minor units. Read and written as bigint.';
COMMENT ON COLUMN payment_authorization_actions.operation_id IS 'Provider idempotency key of the action, created before the provider call.';

-- The last defense of the capture and void rule, behind the application's row
-- lock of the intent: a new action needs a MANUAL intent in REQUIRES_CAPTURE,
-- an AUTHORIZED attempt, and the intent's whole amount. The intent row is
-- locked FOR UPDATE first, so concurrent inserts for one intent are checked
-- one after the other.
CREATE FUNCTION payment_authorization_actions_assert_capturable() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  intent_status varchar;
  intent_mode varchar;
  intent_amount bigint;
  attempt_status varchar;
BEGIN
  SELECT status, capture_mode, amount_minor INTO intent_status, intent_mode, intent_amount
    FROM payment_intents
   WHERE merchant_id = NEW.merchant_id AND id = NEW.payment_intent_id
     FOR UPDATE;
  IF intent_mode <> 'MANUAL' OR intent_status <> 'REQUIRES_CAPTURE' THEN
    RAISE EXCEPTION 'payment_authorization_actions: payment intent % is % with capture mode % and has no hold to act on',
      NEW.payment_intent_id, intent_status, intent_mode
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.amount_minor <> intent_amount THEN
    RAISE EXCEPTION 'payment_authorization_actions: an action of payment intent % must cover its whole amount',
      NEW.payment_intent_id
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT status INTO attempt_status
    FROM payment_attempts
   WHERE merchant_id = NEW.merchant_id AND id = NEW.payment_attempt_id;
  IF attempt_status <> 'AUTHORIZED' THEN
    RAISE EXCEPTION 'payment_authorization_actions: payment attempt % is % and not authorized',
      NEW.payment_attempt_id, attempt_status
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;

CREATE TRIGGER payment_authorization_actions_capturable
AFTER INSERT ON payment_authorization_actions
FOR EACH ROW
EXECUTE FUNCTION payment_authorization_actions_assert_capturable();

-- What an action is never changes, nothing returns to EXECUTING, and a
-- finished action (SUCCEEDED or FAILED) is never updated again. UNKNOWN may
-- still be resolved.
CREATE FUNCTION payment_authorization_actions_reject_invalid_update() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.merchant_id, NEW.payment_intent_id, NEW.payment_attempt_id,
      NEW.processor_account_id, NEW.action, NEW.operation_id,
      NEW.idempotency_record_id, NEW.amount_minor, NEW.currency, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.merchant_id, OLD.payment_intent_id, OLD.payment_attempt_id,
      OLD.processor_account_id, OLD.action, OLD.operation_id,
      OLD.idempotency_record_id, OLD.amount_minor, OLD.currency, OLD.created_at) THEN
    RAISE EXCEPTION 'payment_authorization_actions: the identity of an action cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status IN ('SUCCEEDED', 'FAILED') THEN
    RAISE EXCEPTION 'payment_authorization_actions: a finished action cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.status = 'EXECUTING' AND OLD.status <> 'EXECUTING' THEN
    RAISE EXCEPTION 'payment_authorization_actions: an action cannot return to EXECUTING'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER payment_authorization_actions_restrict_update
BEFORE UPDATE ON payment_authorization_actions
FOR EACH ROW
EXECUTE FUNCTION payment_authorization_actions_reject_invalid_update();

-- Actions are the history of the hold: deleting one would hide a capture or
-- free the intent for another action, so deletion is rejected for every
-- statement.
CREATE FUNCTION payment_authorization_actions_reject_delete() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'payment_authorization_actions: % is not allowed', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER payment_authorization_actions_restrict_delete
BEFORE DELETE OR TRUNCATE ON payment_authorization_actions
FOR EACH STATEMENT
EXECUTE FUNCTION payment_authorization_actions_reject_delete();
